#!/usr/bin/env python3
"""
Convert Claude Code raw transcripts to contest log format.

Reads:  ~/.claude/projects/E-----OpenVela/*.jsonl  (Claude Code raw transcripts)
Writes: <repo_root>/logs/<github_login>/<date>/claude-code__<session_id>.jsonl

Usage:
  python scripts/convert-transcripts.py                    # convert all sessions
  python scripts/convert-transcripts.py --session <id>    # convert one session
  python scripts/convert-transcripts.py --dry-run          # preview without writing
"""
from __future__ import annotations

import argparse
import json
import os
import re
import sys
from datetime import datetime, timezone
from pathlib import Path

# ── Config ──────────────────────────────────────────────────────────────────
TEAM_ID = "contest2026-237-xinghe"
GITHUB_LOGIN = "Zeng-BY"
TOOL = "claude-code"
SCHEMA_VERSION = "1.0"

CLAUDE_PROJECTS_DIR = Path.home() / ".claude" / "projects"
# The OpenVela project dir (path-encoded by Claude Code)
OPENVELA_PROJECT_DIR = CLAUDE_PROJECTS_DIR / "E-----OpenVela"

# Redaction rules
REDACT_RULES = [
    (re.compile(r"sk-[A-Za-z0-9_-]{20,}"), "sk-***REDACTED***"),
    (re.compile(r"ghp_[A-Za-z0-9]{36}"), "ghp_***REDACTED***"),
    (re.compile(r"Bearer\s+[A-Za-z0-9._\-+/=]+"), "Bearer ***REDACTED***"),
]


def redact(text: str) -> tuple[str, int]:
    """Apply redaction rules. Returns (redacted_text, count)."""
    count = 0
    for pattern, replacement in REDACT_RULES:
        text, n = pattern.subn(replacement, text)
        count += n
    return text, count


def extract_session_id(jsonl_path: Path) -> str | None:
    """Extract session ID from the first 'mode' line."""
    with open(jsonl_path, encoding="utf-8") as f:
        for line in f:
            data = json.loads(line)
            if data.get("type") == "mode":
                return data.get("sessionId")
    return jsonl_path.stem  # fallback to filename


def extract_timestamp(data: dict) -> str:
    """Extract ISO timestamp from a transcript entry."""
    ts = data.get("timestamp", "")
    if not ts:
        return datetime.now(timezone.utc).isoformat()
    # Ensure it ends with Z or has timezone
    if not ts.endswith("Z") and "+" not in ts and ts.count(":") >= 2:
        ts += "Z"
    return ts


def map_role(data: dict) -> str | None:
    """Map Claude Code transcript type to contest log role."""
    tp = data.get("type", "")

    if tp == "user":
        return "user"
    elif tp == "assistant":
        return "assistant"
    elif tp == "system":
        return "system"
    elif tp == "attachment":
        # Attachments can be tool results, hook outputs, etc.
        attachment = data.get("attachment", {})
        att_type = attachment.get("type", "")
        if att_type in ("tool_result", "tool_use"):
            return "tool"
        # Hook successes/failures are system-level
        if att_type in ("hook_success", "hook_error"):
            return "system"
        return None  # skip other attachments (file-history-snapshot, etc.)
    return None


def extract_text(data: dict) -> str:
    """Extract text content from a transcript entry."""
    tp = data.get("type", "")

    if tp == "user":
        msg = data.get("message", {})
        if isinstance(msg, dict):
            content = msg.get("content", "")
            if isinstance(content, str):
                return content
            elif isinstance(content, list):
                # Multi-part content
                parts = []
                for block in content:
                    if isinstance(block, dict) and block.get("type") == "text":
                        parts.append(block.get("text", ""))
                return "\n".join(parts)
        return str(msg) if msg else ""

    elif tp == "assistant":
        msg = data.get("message", {})
        if isinstance(msg, dict):
            content = msg.get("content", "")
            if isinstance(content, str):
                return content
            elif isinstance(content, list):
                parts = []
                for block in content:
                    if isinstance(block, dict):
                        if block.get("type") == "text":
                            parts.append(block.get("text", ""))
                        elif block.get("type") == "thinking":
                            parts.append(f"[thinking]{block.get('thinking', '')}")
                return "\n".join(parts)
        return str(msg) if msg else ""

    elif tp == "system":
        return data.get("content", "")

    elif tp == "attachment":
        attachment = data.get("attachment", {})
        att_type = attachment.get("type", "")
        if att_type == "tool_result":
            return str(attachment.get("content", ""))
        elif att_type == "hook_success":
            stdout = attachment.get("stdout", "")
            return f"[hook:{attachment.get('hookName', 'unknown')}] {stdout}"
        elif att_type == "hook_error":
            return f"[hook-error:{attachment.get('hookName', 'unknown')}] {attachment.get('stderr', '')}"
        return ""

    return ""


def extract_tool_info(data: dict) -> dict:
    """Extract tool-specific fields for role=tool events."""
    attachment = data.get("attachment", {})
    result = {}
    if attachment.get("type") == "tool_result":
        result["tool_name"] = attachment.get("toolName", "unknown")
        result["tool_call_id"] = attachment.get("toolUseID", "")
        result["output"] = attachment.get("content", "")
    return result


